// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzed_from, address fuzzed_caddress, address[] memory fuzzed_tos, uint256 fuzzed_v) public {
        vm.assume(fuzzed_tos.length > 0);
        bool success;
        try c.transfer(fuzzed_from, fuzzed_caddress, fuzzed_tos, fuzzed_v) returns (bool ret) {
            success = ret;
        } catch {
            return;
        }
        assertTrue(success);
    }
}
